code_example:
class Widget {
public:
    Widget() { /* ... */ }
};

void demo_construction() {
    // Version 1: Using make_shared
    // - Avoids repeating "Widget"
    // - Performs a single heap allocation for the Widget and the control block
    // - Better performance and exception safety
    auto spw1 = std::make_shared<Widget>();

    // Version 2: Direct construction with new
    // - Repeats the type "Widget"
    // - Performs two heap allocations:
    //   1. 'new Widget()' for the object
    //   2. A second, internal allocation for the control block (ref counts)
    // - Slower and potentially exception-unsafe (see other concept)
    std::shared_ptr<Widget> spw2(new Widget());

    // For unique pointers, the argument is about clarity and safety, not performance.
    // Both approaches result in one allocation.
    auto upw1 = std::make_unique<Widget>();                 // Preferred: concise, safe
    std::unique_ptr<Widget> upw2(new Widget());             // Verbose, less safe
}
